package com.aoo.bcg.common.invite;
import java.net.URI;import java.net.URISyntaxException;import java.util.Set;
/** Exact HTTPS share-domain policy; no caller-controlled redirect or protocol is accepted. */
public final class ShareLinkPolicy{private static final String PATH="/invite/join";private final Set<String>allowedHosts;public ShareLinkPolicy(Set<String>allowedHosts){this.allowedHosts=Set.copyOf(allowedHosts);if(this.allowedHosts.isEmpty()||this.allowedHosts.stream().anyMatch(host->host==null||host.isBlank()||host.contains(":")))throw new IllegalArgumentException("invalid share hosts");}public URI build(String host,String signedToken){requireHost(host);if(signedToken==null||!signedToken.matches("[A-Za-z0-9._~-]{20,4096}"))throw new IllegalArgumentException("invalid signed token");try{return new URI("https",host,PATH,"invite="+signedToken,null);}catch(URISyntaxException impossible){throw new IllegalArgumentException("invalid share link",impossible);}}public URI validate(String raw){try{URI uri=new URI(raw);if(!"https".equals(uri.getScheme())||uri.getUserInfo()!=null||uri.getPort()!=-1||!PATH.equals(uri.getPath())||uri.getFragment()!=null)throw new SecurityException("share link shape rejected");requireHost(uri.getHost());String query=uri.getRawQuery();if(query==null||!query.matches("invite=[A-Za-z0-9._~-]{20,4096}"))throw new SecurityException("share link parameters rejected");return uri;}catch(URISyntaxException error){throw new SecurityException("share link syntax rejected",error);}}private void requireHost(String host){if(host==null||!allowedHosts.contains(host))throw new SecurityException("share domain rejected");}}
